  NV = `أسلوب اللعب الأكثر ابتكارًا`,
  PV = `أفضل لعبة تكون سيئًا بها`,
  FV = `أفضل موسيقى تصويرية`,
  IV = `لعبة رائعة بقصة ثرية`,
  LV = `اجلس واسترخ`,
  RV = `لا تقترح فئة محددة، وبدلًا من ذلك دع معجبيك يختارون الفئة التي يعتقدون أنها الأنسب للعبة الخاصة بك. سيتضمن الحدث رابطًا يُوصّلك إلى صفحة الترشيحات.`,
  zV = `دون فئة`,
  BV = `ربما كان أسلوب لعبها الغامر أو قصتها المثيرة... شخصياتها المصممة جيدًا أو التصميم الأنيق أو اللعب الجماعي الذي لا يقاوم. مهما كان السبب، فإن الفائزة بجائزة أفضل لعبة لعام 2020 هي تحفة كلاسيكية.`,
  VV = `لعبة الـVR لهذا العام لا تكتفي بمحاكاة الواقع العادي، بل تتفوّق عليه. إنها تستغل إمكانيات الـVR بالكامل، وتدفع حدود العالم الافتراضي إلى آفاق جديدة.`,
  HV = `لقد صدرت هذه اللعبة منذ فترة. فريق التطوير تجاوز منذ زمن مرحلة إطلاق هذا المشروع الإبداعي، لكنهم ما زالوا يعتنون بلعبتهم ويواصلون دعمها. وحتى اليوم، وبعد كل هذه السنوات، لا تزال هذه اللعبة تحصل على محتوى جديد.`,
  UV = `هناك بعض الألعاب التي لا تكتمل متعتها عند اللعب بمفردك. ربما تحتاج إلى صديق يحمي ظهرك… أو ربما إلى صديق تطعَنُه في ظهره! في كلتا الحالتين، المتعة بانتظار من يجمع أصدقاءه ويخوض هذه اللعبة معهم.`,
  WV = `لا يطمح الأسلوب البصري إلى تحقيق الدقة الرسومية الواقعية (على الرغم من أن ذلك هدف جيد في حد ذاته)… إنه يصف مظهرًا وشعورًا مميزين يغمران اللعبة بأكملها.`,
  GV = `مصممو هذه اللعبة في طليعة التجارب الإبداعية، يقدمون منظورًا جديدًا ومفاجآت مثيرة. لقد أبهرت وألهمت وأمتعت هذه اللعبة بحداثة لم تُلعب من قبل.`,
  KV = `هذه هي اللعبة التي تكافئ الإصرار، وليست للجبناء. إنها أصعب لعبة أحببناها على الإطلاق.`,
  qV = `هذا البطل المجهول يستحق الشهرة بسبب موسيقاه المذهلة. إنها الموسيقى التصويرية الأصلية الأكثر نجاحًا! `,
  JV = `في بعض الأيام، لا يرضي شغفنا إلا لعبة تركز على السرد القصصي، وهذه اللعبة تفي بالغرض بقوة. إنها مشوّقة كأكثر المسلسلات درامية، ومتقنة كأروع سيناريوهات المسلسلات التلفزيونية المرموقة. تهانينا! على لعبة جعلتنا نشعر بكل ذلك!`,
  YV = `هذه اللعبة هي الملاذ ليوم حافل. إنها سلسة ومريحة وتسمح لهمومك بالاندثار. هذه اللعبة هي لحظتك للتمتع بالسلام الداخلي.`,
  XV = `هل تريد تغيير ترشيحك؟`,
  ZV = `يمكنك ترشيح لعبة واحدة فقط لكل فئة، وقد قمت بالفعل بترشيح %1$s لهذه الفئة. هل ترغب بترشيح %2$s بدلًا منها؟`,
  QV = `صوّت`,
