  tH = `هل تريد تغيير تصويتك؟`,
  nH = `يمكنك التصويت للعبة واحدة فقط لكل فئة، وقد قمت بالفعل بالتصويت لـ%1$s لهذه الفئة. هل ترغب في تغيير تصويتك إلى %2$s؟`,
  rH = `يبدو أن حسابك مقيد. لمنع إساءة استخدام الترشيحات، يجب إنفاق 5 دولارات أمريكية على Steam من أجل المشاركة في جوائز Steam. %1$s لمزيد من المعلومات.`,
  iH = `يبدو أن حسابك مقيد. لمنع إساءة استخدام التصويت، يجب إنفاق 5 دولارات أمريكية على Steam من أجل المشاركة في جوائز Steam. %1$s لمزيد من المعلومات.`,
