  RH = `لقد صدرت هذه اللعبة منذ فترة. فريق التطوير تجاوز منذ زمن مرحلة إطلاق هذا المشروع الإبداعي، لكنهم ما زالوا يعتنون بلعبتهم ويواصلون دعمها. وحتى اليوم، وبعد كل هذه السنوات، لا تزال هذه اللعبة تحصل على محتوى جديد.`,
