  VH = `مصممو هذه اللعبة في طليعة التجارب الإبداعية، يقدمون منظورًا جديدًا ومفاجآت مثيرة. لقد أبهرت وألهمت وأمتعت هذه اللعبة بحداثة لم تُلعب من قبل.`,
  HH = `هذه هي اللعبة التي تكافئ الإصرار، وليست للجبناء. إنها أصعب لعبة أحببناها على الإطلاق.`,
  UH = `هذا البطل المجهول يستحق الشهرة بسبب موسيقاه المذهلة. إنها الموسيقى التصويرية الأصلية الأكثر نجاحًا! `,
  WH = `في بعض الأيام، لا يرضي شغفنا إلا لعبة تركز على السرد القصصي، وهذه اللعبة تفي بالغرض بقوة. إنها مشوّقة كأكثر المسلسلات درامية، ومتقنة كأروع سيناريوهات المسلسلات التلفزيونية المرموقة. تهانينا! على لعبة جعلتنا نشعر بكل ذلك!`,
  GH = `هذه اللعبة هي الملاذ ليوم حافل. إنها سلسة ومريحة وتسمح لهمومك بالاندثار. هذه اللعبة هي لحظتك للتمتع بالسلام الداخلي.`,
  KH = `كانت هذه اللعبة جيدة جدًا، وأردت أخذها إلى كل مكان. وقد فعلت! ولحسن الحظ، فإن كل ما جعلها قابلة للعب على مكتبك أصبح أفضل في أثناء التنقل.`,
  qH = `VR فقط`,
  JH = `مدعومة بالـVR`,
  YH = `بقي %1$s حتى السحب العشوائي التالي!`,
  XH = `الوقت المتبقي حتى السحب العشوائي التالي.`,
  ZH = `استمر في المشاهدة لفرصة للفوز!`,
  QH = `السحب العشوائي جارٍ`,
  $H = `هناك عدد من الفائزين المحظوظين حتى الآن!`,
  eU = `انتهت المسابقة الآن، شكرًا لمشاركتكم.`,
  tU = `لقد انتهى السحب الآن مع %1$s من الفائزين المحظوظين، شكرًا لمشاركتك.`,
  nU = `انقر لمعرفة المزيد عن الجوائز والفائزين والقواعد`,
  rU = `تحقق كل يوم للحصول على هدية جديدة من الإمبراطور!`,
