  epe = `إذا كنت ترغب في تغيير الإعداد لاحقًا، يمكنك العثور عليه في <1>إعدادات حساب Steam > البيانات والتصفح</1>`,
  tpe = `تعرف على المزيد`,
  npe = `توافق Steam Deck`,
  rpe = `Steam Deck Verified - آراء وملاحظات اللاعبين`,
  ipe = `لا تتوفر بيانات`,
  ape = `يوافق %1$s من المشاركين في الاستبيان على تقييم هذه اللعبة %2$s.`,
  ope = `وللتوضيح، فإن متوسط ​​الموافقة على التقييم عبر جميع ألعاب Deck Verified هو %1$s.`,
  spe = `%1$s%`,
  cpe = `نعرض هذه البيانات لأنه على الرغم من موافقة اللاعبين بأغلبية ساحقة على تصنيف التوافق للألعاب (أكثر من %1$s%)، فإن فهم تجارب اللاعبين الذين لا يوافقون على هذا التصنيف قد يكون مفيدًا، خصوصًا فيما يتعلق بلعبة أو تحديث معين.`,
  lpe = `الأداء`,
  upe = `وضوح الخط`,
