  wpe = `ملاحظة: لا تتوفر بيانات التباين حاليًا، ولكن من المقرر إضافتها خلال المرحلة التجريبية. وعند توفرها ستتمكن من معرفة ما إذا كان معدل الإطارات مستقرًا أم يتقلب بشكل كبير.`,
